import{_ as t,o as e,a as i,b as s}from"./app.C41L12d5.js";const r="/ascendc.github.io/assets/no_partial_out.Bo0vaMVn.png",n="/ascendc.github.io/assets/partial_out.lLf4Q7Vj.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"单次矩阵乘局部输出","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/single_matmul_local_output"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/single_matmul_local_output.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/single_matmul_local_output.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1786954352000}'),l={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/single_matmul_local_output.md"};function p(o,a,_,c,d,m){return e(),i("div",null,[...a[0]||(a[0]=[s('<div><article class="markdown-body"><h1>单次矩阵乘局部输出<span id="ZH-CN_TOPIC_0000002500548100"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002299615601_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>单次矩阵乘局部输出，又称Partial Output。如<a href="../basics.html">基础知识</a>中所述，一次Iterate计算过程中，会按K方向进行一次或多次基本块计算，其中的一次基本块计算为baseM*baseK和baseK*baseN大小的输入数据进行计算得到baseM*baseN大小的结果；每次基本块计算的结果进行累加后，便得到baseM*singleCoreK和singleCoreK*baseN大小的输入数据计算得到的结果baseM*baseN，并将其作为一次Iterate的最终结果输出。</p><p>开启Partial Output功能后，调用Iterate接口不会进行K轴累加，只进行单次基本块计算。用户可以通过GetTensorC接口获取对应的单片数据，最后自行进行K轴上的累加。</p><p><strong>图1</strong> 未开启Partial Output功能计算示意图<span id="zh-cn_topic_0000002299615601_fig59018597286"></span><br><img src="'+r+'" alt title="未开启Partial-Output功能计算示意图"></p><p><strong>图2</strong> 开启Partial Output功能计算示意图<span id="zh-cn_topic_0000002299615601_fig990633219319"></span><br><img src="'+n+`" alt title="开启Partial-Output功能计算示意图"></p><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002299615601_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>矩阵乘计算结果不需要累加，只需要输出baseM*baseK和baseK*baseN的计算结果baseM*baseN。例如需要先获取单次基本块计算的数据进行反量化，再累加得到最终结果。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002299615601_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>该功能仅支持<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/MatmulConfig.html">MDL模板</a>。</li><li>获取矩阵乘计算结果时，仅支持调用Iterate和GetTensorC接口的连续写模式，不支持非连续写模式以及IterateAll接口获取计算结果，连续写模式的介绍请参考<a href="../../../../../api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetTensorC.html">GetTensorC</a>。</li><li>该功能不支持带有Bias矩阵的Matmul计算，即不支持输入Bias矩阵。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002299615601_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_partial_output">开启Partial Output功能的算子样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 配置MDL模板，开启Partial Output
constexpr static MatmulConfigMode configMode = MatmulConfigMode::CONFIG_MDL;
constexpr static MatmulFuncParams funcParams = {
  false, false, false, false, 0, IterateOrder::UNDEF, ScheduleType::INNER_PRODUCT, true, true,
  true /* isPartialOutput */
};
constexpr static MatmulConfig CFG_PARTIAL = GetMMConfig&lt;configMode&gt;(funcParams);
Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CFG_PARTIAL&gt; mm;
REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);
mm.Init(&amp;tiling);
mm.SetTensorA(gmA, isTransposeA);
mm.SetTensorB(gmB, isTransposeB);
while (mm.Iterate()) {
    mm.GetTensorC(tmpGmC[dstOffset], false, true);
    dstOffset += baseM * baseN;
    // 其他操作
}
</code></pre></div></article></div>`,1)])])}const g=t(l,[["render",p]]);export{h as __pageData,g as default};
